class Skiplist {
    static const int LEVELS = 16;
    struct Node {
        int value;
        vector<Node*> next;
        Node(int v, int level) : value(v), next(level, nullptr) {}
    };
    Node* head;
    mt19937 rng;
    int randomLevel() {
        int level = 1;
        while (level < LEVELS && (rng() & 1u)) ++level;
        return level;
    }
public:
    Skiplist() : head(new Node(-1, LEVELS)), rng(random_device{}()) {}
    ~Skiplist() {
        Node* p = head;
        while (p) {
            Node* next = p->next[0];
            delete p;
            p = next;
        }
    }
    bool search(int target) {
        Node* p = head;
        for (int l = LEVELS - 1; l >= 0; --l)
            while (p->next[l] && p->next[l]->value < target)
                p = p->next[l];
        p = p->next[0];
        return p && p->value == target;
    }
    void add(int num) {
        Node* update[LEVELS];
        Node* p = head;
        for (int l = LEVELS - 1; l >= 0; --l) {
            while (p->next[l] && p->next[l]->value < num)
                p = p->next[l];
            update[l] = p;
        }
        int level = randomLevel();
        Node* node = new Node(num, level);
        for (int l = 0; l < level; ++l) {
            node->next[l] = update[l]->next[l];
            update[l]->next[l] = node;
        }
    }
    bool erase(int num) {
        Node* update[LEVELS];
        Node* p = head;
        for (int l = LEVELS - 1; l >= 0; --l) {
            while (p->next[l] && p->next[l]->value < num)
                p = p->next[l];
            update[l] = p;
        }
        Node* node = p->next[0];
        if (!node || node->value != num) return false;
        for (int l = 0; l < static_cast<int>(node->next.size()); ++l)
            update[l]->next[l] = node->next[l];
        delete node;
        return true;
    }
};
